import re
L=open('The_Method_1_6___The_Register-2.md',encoding='utf-8').read().split('\n')
nums=[]
for i,l in enumerate(L,1):
    if i<75 or not l.startswith('### '): continue
    for n in re.findall(r'\b\d{3,4}\b', l[4:]): nums.append((int(n),i))
seq=[n for n,_ in nums]
print('  count:', len(seq), ' min:', min(seq), ' max:', max(seq))
print('  strictly ascending:', all(seq[k]<seq[k+1] for k in range(len(seq)-1)))
dup=[n for n in set(seq) if seq.count(n)>1]
print('  duplicates:', dup if dup else 'NONE')
gaps=[]; 
for k in range(len(seq)-1):
    if seq[k+1]!=seq[k]+1: gaps.append((seq[k],seq[k+1]))
print('  gaps:', len(gaps))
for g in gaps[:12]: print('     ',g)
